'use strict';
// The express-server SHAPE, reduced to one vendorable package: a handler
// function dispatched by method+path, a response composed through the
// OutgoingMessage header store, a request body read through the
// data/end stream, and a self-request over the island's own http client.
//
// Every leg here is one that real express@5 exercises when it serves
// traffic from inside the island:
//   * http.createServer(app) where `app` is an ordinary function —
//     express's app.listen() shape;
//   * res.setHeader/statusCode/end and res.writeHead(status, obj), which
//     is what finalhandler uses on the 404 path (its headers go on the
//     WIRE without becoming readable — Node's rule);
//   * req.unpipe() + a request-body read, which is finalhandler's flush
//     and body-parser's read;
//   * Buffer's STATIC surface copied with `for (key in Buffer)` — how
//     safer-buffer builds the Buffer that iconv-lite, raw-body and
//     body-parser then use. A class's statics are non-enumerable, so an
//     island Buffer that does not republish them leaves that copy empty
//     and a JSON body parse dies deep inside a decoder.
//
// Node is the oracle: everything printed must be reproducible on both
// lanes, so the Date header and the ephemeral port stay out of the report.
const http = require('http');

// safer-buffer's copy, verbatim in spirit.
function saferBuffer() {
  const Safer = {};
  for (const key in Buffer) {
    if (!Object.prototype.hasOwnProperty.call(Buffer, key)) continue;
    if (key === 'allocUnsafe' || key === 'allocUnsafeSlow') continue;
    Safer[key] = Buffer[key];
  }
  return Safer;
}

function app(req, res) {
  const url = req.url;
  if (req.method === 'GET' && url === '/text') {
    const body = 'hello from srvzoo';
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Content-Length', Buffer.byteLength(body));
    res.setHeader('X-Custom', 'yes');
    res.end(body);
    return;
  }
  if (req.method === 'GET' && url === '/json') {
    const body = JSON.stringify({ ok: true, n: 42 });
    res.statusCode = 201;
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('Content-Length', Buffer.byteLength(body));
    res.end(body);
    return;
  }
  if (req.method === 'POST' && url === '/echo') {
    // The body-parser read: chunks in, one Buffer out, decoded through
    // the safer-buffer static surface.
    const S = saferBuffer();
    const chunks = [];
    req.on('data', (c) => { chunks.push(c); });
    req.on('end', () => {
      const raw = S.concat(chunks);
      const parsed = JSON.parse(raw.toString('utf8'));
      const body = JSON.stringify({ got: parsed, isBuf: S.isBuffer(raw) });
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Content-Length', Buffer.byteLength(body));
      res.end(body);
    });
    return;
  }
  // finalhandler's 404: unpipe, then a writeHead whose headers go on the
  // WIRE without entering the readable store — Node's rule, pinned here
  // by reporting getHeaderNames() in the body (it must be empty).
  req.unpipe();
  const names = JSON.stringify(res.getHeaderNames());
  const body = 'Cannot ' + req.method + ' ' + url + ' names=' + names;
  res.writeHead(404, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': String(Buffer.byteLength(body)),
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(body);
}

function once(fn) {
  let done = false;
  return (...a) => { if (!done) { done = true; fn(...a); } };
}

/** Runs the probes strictly one at a time so the report is causally
 * ordered on both lanes, then closes the server. */
function drive(port, out, finish) {
  const probes = [
    ['GET', '/text', null],
    ['GET', '/json', null],
    ['POST', '/echo', JSON.stringify({ hi: 'there', xs: [1, 2, 3] })],
    ['GET', '/nope', null],
  ];
  let i = 0;
  const step = () => {
    if (i === probes.length) { finish(); return; }
    const [method, path, payload] = probes[i++];
    const headers = {};
    if (payload !== null) {
      headers['Content-Type'] = 'application/json';
      headers['Content-Length'] = String(Buffer.byteLength(payload));
    }
    const creq = http.request(
      { host: '127.0.0.1', port, path, method, headers },
      (cres) => {
        out.push('--- ' + method + ' ' + path);
        out.push('status ' + cres.statusCode + ' ' + cres.statusMessage);
        for (const name of ['content-type', 'content-length', 'x-custom',
                            'x-content-type-options', 'connection']) {
          const v = cres.headers[name];
          if (v !== undefined) out.push(name + ': ' + v);
        }
        let body = '';
        cres.on('data', (c) => { body += c.toString('utf8'); });
        cres.on('end', () => {
          out.push('body ' + JSON.stringify(body));
          step();
        });
      },
    );
    creq.on('error', (e) => { out.push('client error ' + e.message); step(); });
    if (payload !== null) creq.write(payload);
    creq.end();
  };
  step();
}

exports.report = function report(done) {
  const out = [];
  // The static surface safer-buffer needs — proof the copy is not empty.
  const S = saferBuffer();
  out.push('safer isBuffer=' + (typeof S.isBuffer) + ' from=' + (typeof S.from) +
           ' byteLength=' + (typeof S.byteLength) + ' concat=' + (typeof S.concat));

  const server = http.createServer(app);
  const finish = once(() => {
    server.close(() => { done(out.join('\n')); });
  });
  server.on('error', (e) => { out.push('server error ' + e.message); finish(); });
  server.listen(0, '127.0.0.1', () => {
    const addr = server.address();
    out.push('listening family=' + addr.family + ' address=' + addr.address +
             ' port>0=' + (addr.port > 0));
    drive(addr.port, out, finish);
  });
};
